import { Component, Input, Output, EventEmitter, OnChanges, SimpleChanges } from '@angular/core';
import { Message, ConversationData } from '@/app/core/models';
import { highlightText } from '@/app/core/utils/search.utils';
import { conversationsData } from '@/app/core/mock/conversations.data';

@Component({
    selector: 'app-message-list',
    template: `
    <div *ngIf="!isCollapsed" class="w-[390px] shrink-0 border-r border-[#e6e6e6] bg-white flex flex-col h-full relative">
      
      <!-- Search & Filters Header -->
      <div class="p-3 border-b border-[#e6e6e6]">
        <div class="flex gap-3 items-center mb-3">
          <!-- Search Input -->
          <div class="flex-1 relative">
            <div class="absolute left-3 top-1/2 -translate-y-1/2">
              <app-icon name="search" size="14"></app-icon>
            </div>
            <input
              type="text"
              placeholder="Search"
              [ngModel]="searchQuery"
              (ngModelChange)="searchChange.emit($event)"
              class="w-full pl-9 pr-9 py-1.5 text-sm border border-[#ccc] rounded bg-white focus:outline-none focus:border-[#007a91]"
            />
            <button
                *ngIf="searchQuery"
                (click)="searchChange.emit('')"
                class="absolute right-3 top-1/2 -translate-y-1/2 hover:opacity-80 transition-opacity"
            >
                <app-icon name="search-close" size="14"></app-icon>
            </button>
          </div>

          <!-- Filter Button -->
          <div class="flex items-center gap-2">
            <button class="p-2.5 rounded transition-colors border border-transparent hover:bg-gray-100 text-[#262626]">
              <app-icon name="filter" size="18"></app-icon>
            </button>
          </div>
        </div>

        <!-- Folder Dropdown Trigger (Simplified for Phase 4) -->
        <div class="relative" appClickOutside (clickOutside)="isFolderDropdownOpen = false">
            <div 
                (click)="isFolderDropdownOpen = !isFolderDropdownOpen"
                class="flex items-center justify-between cursor-pointer w-full group outline-none pb-1 border-b border-[#ccc] hover:border-transparent transition-colors"
                [class.border-transparent]="isFolderDropdownOpen"
            >
                <div class="flex items-center gap-2 text-xl font-bold text-[#262626] group-hover:text-[#007a91]" [class.text-[#007a91]]="isFolderDropdownOpen">
                    <span>{{ selectedFolder }}</span>
                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" class="transition-transform duration-200 text-current" [class.rotate-180]="isFolderDropdownOpen">
                        <path d="M6 9l6 6 6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                    </svg>
                </div>
                <div class="text-sm">
                    <span class="font-bold">{{ folderUnreadCount }}</span>
                    <span class="text-[#666]">/{{ folderTotalCount }} unread</span>
                </div>
            </div>

            <!-- Folder Dropdown Content -->
            <div *ngIf="isFolderDropdownOpen" class="absolute top-full left-0 mt-1 bg-white rounded shadow-lg border border-[#262626] z-50 flex flex-col w-[200px]">
                <div class="flex flex-col py-2">
                    <div 
                        *ngFor="let folder of ['All Folders', 'Inbox', 'Drafts', 'Deleted Items']" 
                        (click)="selectFolder(folder); isFolderDropdownOpen = false"
                        class="flex items-center px-4 py-3 cursor-pointer hover:bg-gray-50 gap-2"
                    >
                        <div class="w-4 h-4 rounded-full border border-[#262626] flex items-center justify-center p-0.5">
                            <div *ngIf="selectedFolder === folder" class="w-full h-full rounded-full bg-[#007a91]"></div>
                        </div>
                        <span class="text-[#262626] font-bold text-base capitalize">{{ folder }}</span>
                    </div>
                </div>
            </div>
        </div>
      </div>

      <!-- Content -->
      <div *ngIf="isLoading" class="flex-1 overflow-hidden">
        <app-message-list-skeleton></app-message-list-skeleton>
      </div>

      <div *ngIf="!isLoading" class="flex-1 overflow-y-auto message-list-scrollbar">
         <!-- Messages Loop -->
         <div 
            *ngFor="let message of filteredMessages"
            (click)="selectMessage.emit(message.id)"
            class="px-3 py-3 border-b border-[#ccc] cursor-pointer transition-colors"
            [class.bg-[#e7f8fb]]="selectedMessageId === message.id"
            [class.hover:bg-gray-50]="selectedMessageId !== message.id"
         >
            <div class="flex items-center gap-2">
                <!-- Checkbox (Hidden for now, adds complexity, can add later) -->
                
                <div class="flex-1 min-w-0">
                    <div class="flex items-center justify-between mb-2">
                        <app-company-display
                            [companies]="message.companies"
                            [isBold]="message.unreadCount > 0"
                        ></app-company-display>
                        <span class="text-xs text-[#262626] font-normal shrink-0">{{ message.time }}</span>
                    </div>

                    <div class="flex items-center justify-between mb-2">
                        <span class="text-base truncate" [class.font-bold]="message.unreadCount > 0">
                            {{ getSenderDisplay(message) }}
                        </span>
                        <div class="flex items-center gap-1">
                            <app-icon *ngIf="message.isTodo" name="todo" size="14"></app-icon>
                            <app-icon *ngIf="message.hasAttachment" name="attachment" size="14"></app-icon>
                        </div>
                    </div>

                    <div class="flex items-center justify-between">
                         <span class="text-sm text-[#262626] truncate flex-1" [class.font-bold]="message.unreadCount > 0">
                            <span [innerHTML]="highlightSubject(message.subject)"></span>
                         </span>
                         <div *ngIf="message.unreadCount > 0" class="ml-2 px-1.5 py-0.5 rounded text-xs font-bold text-white shrink-0" [class.bg-[#666]]="message.isEntered" [class.bg-[#e2001a]]="!message.isEntered">
                            {{ message.unreadCount }}
                         </div>
                    </div>
                </div>
            </div>
         </div>
      </div>

      <!-- Collapse Button -->
      <button
        (click)="toggleCollapse.emit()"
        class="absolute right-0 top-1/2 -translate-y-1/2 translate-x-1/2 w-[30px] h-[30px] bg-white rounded-lg shadow-[2px_2px_7px_0_rgba(0,0,0,0.25)] hover:bg-gray-50 flex items-center justify-center transition-colors z-10"
        title="Collapse messages list"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#262626" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <polyline points="15 18 9 12 15 6"></polyline>
        </svg>
      </button>

    </div>
  `
})
export class MessageListComponent implements OnChanges {
    @Input() messages: Message[] = [];
    @Input() isLoading = false;
    @Input() selectedMessageId: string | null = null;
    @Input() searchQuery = '';
    @Input() isCollapsed = false;

    @Output() selectMessage = new EventEmitter<string>();
    @Output() toggleCollapse = new EventEmitter<void>();
    @Output() searchChange = new EventEmitter<string>();
    @Output() markAsRead = new EventEmitter<string[]>();
    @Output() markAsUnread = new EventEmitter<string[]>();

    selectedFolder = 'Inbox';
    filteredMessages: Message[] = [];
    isFolderDropdownOpen = false;

    ngOnChanges(changes: SimpleChanges) {
        if (changes['messages'] || changes['searchQuery'] || changes['selectedFolder']) {
            this.filterMessages();
        }
    }

    selectFolder(folder: string) {
        this.selectedFolder = folder;
        this.filterMessages();
    }

    filterMessages() {
        let result = this.messages;

        // Folder Filter
        if (this.selectedFolder !== 'All Folders') {
            result = result.filter(m => m.folder === this.selectedFolder);
        }

        // Search Filter
        if (this.searchQuery && this.searchQuery.trim()) {
            const query = this.searchQuery.toLowerCase();
            result = result.filter(m => {
                if ((m.sender || '').toLowerCase().includes(query)) return true;
                if ((m.subject || '').toLowerCase().includes(query)) return true;

                // Deep search in mock conversations
                const conv = conversationsData[m.id];
                if (conv) {
                    if ((conv.title || '').toLowerCase().includes(query)) return true;
                    if (conv.messages.some((msg: any) => (msg.content || '').toLowerCase().includes(query))) return true;
                }
                return false;
            });
        }

        this.filteredMessages = result;
    }

    get folderUnreadCount() {
        return this.filteredMessages.filter(m => m.unreadCount > 0).length;
    }

    get folderTotalCount() {
        return this.filteredMessages.length;
    }

    highlightSubject(subject: string): string {
        return highlightText(subject, this.searchQuery);
    }

    // Helper to format sender display (Participants logic)
    getSenderDisplay(message: Message): string {
        const conversation = conversationsData[message.id];
        if (conversation && conversation.participantsList) {
            const participants = conversation.participantsList;
            const otherParticipants = participants.filter(p => !p.toLowerCase().includes('(you)') && p !== 'You');
            otherParticipants.sort((a, b) => a.localeCompare(b));

            if (otherParticipants.length > 0) {
                const primaryName = otherParticipants[0];
                const count = participants.length - 1;
                return count > 0 ? `${primaryName} +${count}` : primaryName;
            }
        }
        return message.sender;
    }
}
